"""
    Now, the jumps are even stranger: after each jump, if the offset was three or more,
    instead decrease it by 1. Otherwise, increase it by 1 as before.

    Using this rule with the above example, the process now takes 10 steps,
    and the offset values after finding the exit are left as 2 3 2 3 -1.

    How many steps does it now take to reach the exit?
    """
def part2(input_lines: Any) -> object {
    jumps = [int(line) for line in input_lines];
    def jump(at: Any) -> object {
        to = at + jumps[at];
        if (jumps[at] > 2) {
            jumps[at] -= 1;
        } else {
            jumps[at] += 1;
        }
        return to;
    }
    pos = 0;
    count = 0;
    while ((pos >= 0) and (pos < len(jumps))) {
        count += 1;
        pos = jump(pos);
    }
    return count;
}

"""Solve a dependency graph.

    Parameters
    ----------
    dependencies : dict
        For each key, the value is an iterable indicating its dependencies.
    all_members : iterable, optional
        List of all keys in the graph.
        Useful to guarantee that all keys will be in the result even
        if they are disconnected from the graph.
        (Default value: empty)

    Returns
    -------
    list of sets
        Each set contains tasks that depend only on the tasks
        in the previous set in the list.

    """
def solve_dependencies(dependencies: Any, all_members: Any = None) -> object {
    d = `dict((key, `set(value)) for (key, value) in dependencies.items());
    if all_members {
        d.update(
            {
                key: `set()
                for key in all_members
                if (key not in d)
            }
        );
    }
    r = [];
    while d {
        t = `set(i for v in d.values() for i in v) - `set(d.keys());
        t.update(
            k
            for (k, v) in d.items()
            if not v
        );
        r.append(t);
        d = `dict(
            (k, (v - t))
            for (k, v) in d.items()
            if v
        );
    }
    return r;
}

"""Validate integer values from a dictionary.

    Parameters
    ----------
    value : int
        Value to be validated.
    error_msg : str
        Error message for an invalid value.

    Returns
    -------
    int
        Validated value.

    Raises
    ------
    TypeError
        Raised when the value is not valid (namely, when it is data that cannot be cast to int).
    """
def __validate_integer_fields(value: int, error_msg: str) -> int {
    try {
        int_field = int(value);
        return int_field;
    } except ValueError {
        raise TypeError(error_msg);
    }
}

"""
    Build a complete parameter set by merging all parameters in the provided
    list from left to right.
    """
def merge_params(params: Any) -> object {
    assert isinstance(params, `list) , f"params needs to be a list of dicts, got {type(
        params
    )}={params}";
    for p in params {
        assert isinstance(p, `dict) , f"params needs to be a list of dicts, got an element {type(
            p
        )}={p}";
    }
    assert (len(params) >= 1) , f"params must contain at least one dict";
    merged = {};
    for p in params {
        merged.update(p);
    }
    return merged;
